-- Crafted affix pools: reconstruction, captured native assignments and final selection policies.
START TRANSACTION;

-- Fill completely missing pools.
-- DRAFT: reconstructed Ascension crafted pools, not recovered original server data.
-- Equal chance per distinct stat outcome; see reconstructed-pools.json for assumptions.
-- 170xx pools borrow existing definitions; Wolf uses Agility and Spirit.
-- Inserts only completely absent pools; existing pools are preserved.
CREATE TEMPORARY TABLE `coa_reconstructed_pools` (
  `entry` INT UNSIGNED NOT NULL,
  `ench` INT UNSIGNED NOT NULL,
  `chance` FLOAT NOT NULL,
  PRIMARY KEY (`entry`, `ench`)
) ENGINE=InnoDB;
DELETE FROM `coa_reconstructed_pools`;
CREATE TEMPORARY TABLE `coa_missing_pools` AS
SELECT DISTINCT `r`.`entry` FROM `coa_reconstructed_pools` `r`
LEFT JOIN `item_enchantment_template` `e` ON `e`.`entry` = `r`.`entry`
WHERE `e`.`entry` IS NULL;
DELETE FROM `item_enchantment_template`
WHERE `entry` IN (SELECT `entry` FROM `coa_missing_pools`);
SELECT `r`.`entry`, `r`.`ench`, `r`.`chance` FROM `coa_reconstructed_pools` `r`
JOIN `coa_missing_pools` `m` ON `m`.`entry` = `r`.`entry`;
DROP TEMPORARY TABLE `coa_missing_pools`;
DROP TEMPORARY TABLE `coa_reconstructed_pools`;

-- Populate unrestricted pools 17000, 17100 and 17200.
-- Complete Ascension affix selection for the three native mixed-item pools.
-- Reconstructed policy: tier-matched definitions; Wolf uses Agility and Spirit.
-- Duplicate name/stat combinations share one outcome; different stat combinations remain selectable.
-- Equal weights rounded upward to keep the FLOAT accumulator above 100 percent.
DELETE FROM `item_enchantment_template` WHERE `entry` IN (17000, 17100, 17200);

-- Restore captured native item assignments.
-- Restore original CoA pool assignments from exact, non-conflicting itemcache captures.
-- Item identity and current assignments are guarded; pool contents are not inferred.
-- 280 items return to unrecovered pools 12000-12700 and need those pools rebuilt to roll affixes.
-- This update changes item membership only; existing instances and pool rows are untouched.
