SET `RandomProperty` = 12000, `RandomSuffix` = 0
WHERE `entry` = 727 AND `RandomProperty` = 5168 AND `RandomSuffix` = 0
  AND `name` = 'Notched Shortsword' AND `class` = 2 AND `subclass` = 7
  AND `InventoryType` = 13;
